import{_ as r,o as a,c as d,a2 as o}from"./chunks/framework.CRFziyHp.js";const b=JSON.parse('{"title":"样式与点击动作","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/styles-and-actions.md","filePath":"features/ui-editor/styles-and-actions.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/styles-and-actions.md"};function n(i,t,s,l,h,g){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="样式与点击动作" tabindex="-1">样式与点击动作 <a class="header-anchor" href="#样式与点击动作" aria-label="Permalink to &quot;样式与点击动作&quot;">​</a></h1><p>选中画布上的组件后，右侧 <strong>样式</strong> Tab 与 <strong>属性</strong> 中的 <strong>点击动作</strong> 是美化与交互的两类核心配置。</p><h2 id="通用样式面板" tabindex="-1">通用样式面板 <a class="header-anchor" href="#通用样式面板" aria-label="Permalink to &quot;通用样式面板&quot;">​</a></h2><p>所有画布组件共享同一套 <strong>样式</strong> 字段，单位默认为 <strong>rpx</strong>（响应式像素，750rpx ≈ 屏幕全宽）。</p><h3 id="尺寸" tabindex="-1">尺寸 <a class="header-anchor" href="#尺寸" aria-label="Permalink to &quot;尺寸&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>宽度</td><td>留空为 <code>auto</code>；可填数字或百分比</td></tr><tr><td>高度</td><td>留空为 <code>auto</code>；图片、轮播等常需指定高度</td></tr></tbody></table><h3 id="外边距-margin" tabindex="-1">外边距（margin） <a class="header-anchor" href="#外边距-margin" aria-label="Permalink to &quot;外边距（margin）&quot;">​</a></h3><p>上 / 右 / 下 / 左 四个方向，控制组件与周围内容的间距。</p><h3 id="内边距-padding" tabindex="-1">内边距（padding） <a class="header-anchor" href="#内边距-padding" aria-label="Permalink to &quot;内边距（padding）&quot;">​</a></h3><p>上 / 右 / 下 / 左 四个方向，控制组件 <strong>内部</strong> 内容与边框的距离。</p><h3 id="背景与边框" tabindex="-1">背景与边框 <a class="header-anchor" href="#背景与边框" aria-label="Permalink to &quot;背景与边框&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>背景色</td><td>支持透明（表单说明组件外层建议透明）</td></tr><tr><td>背景图</td><td>从媒体库选择；可选 <strong>铺满裁剪 / 完整显示 / 拉伸铺满</strong></td></tr><tr><td>圆角</td><td>数字，rpx</td></tr><tr><td>边框宽度</td><td>数字，rpx</td></tr><tr><td>边框颜色</td><td>颜色选择器</td></tr></tbody></table><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>透明度</td><td>0~1，默认 1</td></tr><tr><td>阴影</td><td>CSS 阴影字符串，如 <code>0 4rpx 20rpx rgba(0,0,0,0.08)</code></td></tr><tr><td>溢出</td><td>默认 / hidden / visible</td></tr></tbody></table><h3 id="颜色选择器" tabindex="-1">颜色选择器 <a class="header-anchor" href="#颜色选择器" aria-label="Permalink to &quot;颜色选择器&quot;">​</a></h3><p>点击色块打开取色器，支持：</p><ul><li>预设色板</li><li>手动输入 HEX</li><li>透明色（部分场景）</li></ul><hr><h2 id="列表-section-的样式分层" tabindex="-1">列表 Section 的样式分层 <a class="header-anchor" href="#列表-section-的样式分层" aria-label="Permalink to &quot;列表 Section 的样式分层&quot;">​</a></h2><p><strong>笔记列表</strong>、<strong>圈子列表</strong>、<strong>笔记瀑布流</strong> 三类组件结构特殊：</p><table tabindex="0"><thead><tr><th>样式 Tab 中的分组</th><th>作用对象</th></tr></thead><tbody><tr><td><strong>尺寸、外边距</strong></td><td>整个列表区域（section 外壳）</td></tr><tr><td><strong>内边距、背景、圆角、边框</strong></td><td>每一条 <strong>卡片内部</strong></td></tr><tr><td><strong>属性 Tab 中的图标、字号、颜色等</strong></td><td>卡片内具体元素</td></tr></tbody></table><p>面板顶部有灰色提示说明，避免误把卡片背景配在外层。</p><hr><h2 id="点击动作-clickaction" tabindex="-1">点击动作（clickAction） <a class="header-anchor" href="#点击动作-clickaction" aria-label="Permalink to &quot;点击动作（clickAction）&quot;">​</a></h2><p>带交互的组件（按钮、轮播项、金刚区图标、列表行等）可配置 <strong>点击动作</strong>。</p><p>在属性面板点击 <strong>点击动作</strong> 行，弹出动作选择器：</p><h3 id="常见动作类型" tabindex="-1">常见动作类型 <a class="header-anchor" href="#常见动作类型" aria-label="Permalink to &quot;常见动作类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>需填写</th></tr></thead><tbody><tr><td><strong>跳转页面</strong></td><td>打开 App 内某个页面</td><td>选择或输入页面路径</td></tr><tr><td><strong>重定向</strong></td><td>关闭当前页再打开</td><td>页面路径</td></tr><tr><td><strong>切换 Tab</strong></td><td>跳到底部某个 Tab</td><td>Tab 对应页面路径</td></tr><tr><td><strong>重启应用栈</strong></td><td>清空页面栈后打开</td><td>页面路径</td></tr><tr><td><strong>打开外链</strong></td><td>H5 / 小程序 webview</td><td>URL</td></tr><tr><td><strong>打开小程序</strong></td><td>跳转其它小程序</td><td>AppID、路径</td></tr><tr><td><strong>预览图片</strong></td><td>大图预览</td><td>图片地址</td></tr><tr><td><strong>复制文本</strong></td><td>复制到剪贴板</td><td>文本内容</td></tr><tr><td><strong>拨打电话</strong></td><td>调起拨号</td><td>号码</td></tr><tr><td><strong>打开地图</strong></td><td>导航到坐标</td><td>经纬度、名称</td></tr><tr><td><strong>发布弹窗</strong></td><td>打开发布菜单</td><td>一般用于 TabBar 中间按钮</td></tr><tr><td><strong>无动作</strong></td><td>仅展示</td><td>—</td></tr></tbody></table><h3 id="选择页面路径" tabindex="-1">选择页面路径 <a class="header-anchor" href="#选择页面路径" aria-label="Permalink to &quot;选择页面路径&quot;">​</a></h3><p>动作类型为页面跳转时，点击 <strong>选择页面</strong>，从系统内置路由列表中选：</p><ul><li>首页、发现、消息、我的</li><li>笔记详情、圈子详情、搜索</li><li>自定义页面（需带 <code>page_type</code> 参数）</li><li>外卖、闲置等业务页（需模块已开通）</li></ul><p>也可手动输入路径与参数。</p><h3 id="配置示例" tabindex="-1">配置示例 <a class="header-anchor" href="#配置示例" aria-label="Permalink to &quot;配置示例&quot;">​</a></h3><p><strong>金刚区「二手闲置」图标 → 闲置列表</strong></p><ol><li>选中金刚区组件 → 展开对应图标项</li><li>点击动作 → <strong>跳转页面</strong> → 选择闲置相关页面</li></ol><p><strong>轮播图第一张 → 活动自定义页</strong></p><ol><li>轮播图 → 图片 1 → 点击动作 → <strong>跳转页面</strong></li><li>选择自定义页并带上正确的 <code>page_type</code></li></ol><hr><h2 id="筛选标签与列表联动" tabindex="-1">筛选标签与列表联动 <a class="header-anchor" href="#筛选标签与列表联动" aria-label="Permalink to &quot;筛选标签与列表联动&quot;">​</a></h2><p><strong>筛选标签</strong> 组件有两种内容模式（属性面板中 <strong>内容模式</strong>）：</p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>API 联动</strong></td><td>切换 Tab 时，下方 <strong>笔记列表 / 圈子列表 / 瀑布流</strong> 按筛选条件刷新数据</td></tr><tr><td><strong>Tab 面板</strong></td><td>每个 Tab 下可独立配置一小段画布内容（适合静态分区）</td></tr></tbody></table><p>使用 API 联动时：</p><ol><li>列表 section 与筛选标签各配置相同的 <strong>联动 Key</strong>（属性面板中 <code>filterLinkKey</code>）</li><li>筛选标签每个 Tab 可设排序、分类、话题 ID 等筛选参数</li></ol><p>圈子页（forum）联动目标 <strong>固定为笔记</strong>，不可改为圈子。</p><hr><h2 id="表单组件的内嵌样式" tabindex="-1">表单组件的内嵌样式 <a class="header-anchor" href="#表单组件的内嵌样式" aria-label="Permalink to &quot;表单组件的内嵌样式&quot;">​</a></h2><p>表单类组件（单行输入、选项等）除 <strong>样式 Tab 外壳</strong> 外，<strong>属性 Tab</strong> 内还有分组：</p><ul><li>标题样式（字号、颜色、是否显示）</li><li>输入区样式（边框、圆角、背景）</li><li>选项 pill 样式、滑块轨道颜色等</li></ul><p><strong>表单说明</strong> 组件：提示条背景色在 <strong>属性 → 说明样式</strong> 配置；<strong>样式 Tab 背景</strong> 仅作用于外层容器，建议保持透明。</p><hr><h2 id="样式调试技巧" tabindex="-1">样式调试技巧 <a class="header-anchor" href="#样式调试技巧" aria-label="Permalink to &quot;样式调试技巧&quot;">​</a></h2><ol><li><strong>先搭结构再微调</strong>：先用默认样式排好组件顺序，最后统一改间距</li><li><strong>用模块标题分区</strong>：长首页用「模块标题」组件分隔区块</li><li><strong>列表放底部</strong>：笔记列表等数据组件尽量靠下，上方放运营位</li><li><strong>margin 留白</strong>：模块之间常用 <code>marginTop: 20~30</code> rpx</li><li><strong>预览 ≠ 真机</strong>：工具栏预览为截图；最终以 App 内效果为准</li></ol><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features/ui-editor/components-basic">基础元素组件</a></li><li><a href="/features/ui-editor/components-layout">布局导航组件</a></li><li><a href="/features/ui-editor/tabbar">TabBar 配置</a></li></ul>',55)])])}const p=r(e,[["render",n]]);export{b as __pageData,p as default};
